/* nodes details for region "earth", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("earth.nodes",{"nodes":{
"earth-rotation-day-night":{"description":{"zh":"太阳光是平行光，任何时刻只照亮地球的一半；地球绕地轴自西向东自转，每个地方轮流转进亮面和暗面，转一圈就是一天；站在转动的地面上看，太阳就像从东边升起、西边落下。","en":"Sunlight arrives in parallel rays and lights only half the Earth at any moment; the Earth spins west to east on its axis, carrying every place through the bright half and the dark half in turn, one turn per day; seen from the turning ground, the Sun seems to rise in the east and set in the west."},"source":"../earth/astronomy/day-night-rotation/#step2","lessons":[{"slug":"day-night-rotation","step":2,"category":"earth","stage":"primary","primary":true}],"aliases":{"zh":["为什么有白天和黑夜","地球自转","太阳为什么东升西落","晨昏线","自转和公转","一天为什么是 24 小时","昼夜交替","白天黑夜","为什么有白天黑夜","昼夜"],"en":["why is there day and night","Earth’s rotation","why does the sun rise in the east","terminator line","rotation and revolution","why is a day 24 hours","day and night cycle","day and night","why do we have day and night"]}},
"moon-phases":{"description":{"zh":"月亮永远亮半边；从地球看到的亮面比例是 (1 − cos θ)/2，周期约 29.5 天。假设圆轨道与平行光，北半球视角。","en":"The Moon is always half lit; the fraction seen from Earth is (1 − cos θ)/2 with a period of about 29.5 days. Assumes a circular orbit, parallel light and a northern-hemisphere view."},"formula":"f = (1 − cos θ) / 2","source":"../earth/astronomy/moon-phases/#step1","lessons":[{"slug":"moon-phases","step":1,"category":"earth","stage":"primary","primary":true}],"note":"group is earth & space; no atlas group exists for it","aliases":{"zh":["月亮为什么有圆缺","月有阴晴圆缺","月亮圆缺","上弦月 下弦月"],"en":["why does the moon change shape","phases of the moon","half moon","crescent moon"]}},
"contour-lines":{"description":{"zh":"等高线是同一海拔的点连成的线：相邻两条差一个等高距，越密坡越陡，水沿垂直于等高线的最陡方向往低处流。仅为虚构光滑地形的教学模型。","en":"Contour lines join points of equal altitude: neighbours differ by one contour interval, the closer they are the steeper the slope, and water runs downhill perpendicular to them. A teaching model on made-up smooth terrain."},"formula":"gap = Δh / slope","source":"../earth/geo/contour-lines/#step1","lessons":[{"slug":"contour-lines","step":1,"category":"earth","stage":"junior","primary":true}],"note":"No earth-science group in the atlas; group left OTHER. The edge to the existing 'derivative' node is a real link: slope from contour spacing is a rate of change."},
"latitude-longitude":{"description":{"zh":"纬度和经度是球面上的两个角度，合起来定位任意一点；纬线周长随 cos 纬度缩小，球面摊成平面必然变形，最短路是大圆弧，15° 经度对应 1 小时。仅为球形地球的教学模型。","en":"Latitude and longitude are two angles on a sphere that together locate any point; a parallel’s length shrinks with cos latitude, flattening a sphere necessarily distorts, the shortest route is a great-circle arc, and 15° of longitude is one hour. A teaching model of a spherical Earth."},"formula":"L(φ) = 2πR·cos φ","source":"../earth/geo/latitude-longitude/#step1","lessons":[{"slug":"latitude-longitude","step":1,"category":"earth","stage":"junior","primary":true}],"note":"No earth-science group in the atlas; group left OTHER. The edge to the existing 'unit-circle' node is a real link: a parallel's length scales with cos of latitude.","aliases":{"zh":["经纬度","经纬度是什么","经度","纬度"],"en":["latitude","longitude"]}},
"seasons-orbit":{"description":{"zh":"四季来自地轴倾斜约 23.4° 且方向不变，让太阳直射点一年内在南北回归线之间往返，正午太阳高度和昼长随之变化；日地距离只变化约 3%，不是原因。仅为几何模型，不含大气与热惯性。","en":"The seasons come from Earth’s axis being tilted about 23.4° in a fixed direction, so the overhead point swings between the tropics over a year and noon Sun height and day length follow; the Earth–Sun distance changes only about 3% and is not the cause. A geometric model without atmosphere or thermal lag."},"formula":"h = 90° − |φ − δ|","source":"../earth/astronomy/seasons-orbit/#step2","lessons":[{"slug":"seasons-orbit","step":2,"category":"earth","stage":"junior","primary":true}],"note":"No earth-science group in the atlas; group left OTHER. The edge to 'sine' is a real link: noon-altitude intensity is proportional to sin h.","aliases":{"zh":["为什么会有四季","四季是怎么来的","四季成因","夏天为什么热"],"en":["why do we have seasons","why are there seasons","what causes the seasons","why is summer hot"]}},
"atmospheric-circulation":{"description":{"zh":"赤道受热多、极地受热少推动空气环流，地球自转的科里奥利偏转把它拧成三圈与信风、西风带；陆海温差让季风随季节反向。理想化无大陆模型，数值为示意。","en":"More heating at the equator than the poles drives overturning, Coriolis deflection twists it into three cells with trade winds and westerlies, and land–sea contrast reverses monsoons with the season. An idealised model without continents; numbers are schematic."},"formula":"f = 2Ω sin φ","source":"../earth/climate/atmospheric-circulation/#step2","lessons":[{"slug":"atmospheric-circulation","step":2,"category":"earth","stage":"senior","primary":true}],"note":"No earth-science group in the atlas; group left OTHER. Edge sources are existing site pages (seasons-orbit, climate-energy) whose own fragments are merged separately."},
"carbon-cycle":{"description":{"zh":"用大气、陆地、表层海洋、深海与化石燃料五个碳库的账本，展示自然流量平衡、排放累积、碳的去向守恒，以及停排后下降缓慢。五库玩具模型，只显示趋势，不是预测。","en":"A five-reservoir ledger (air, land, surface ocean, deep ocean, fossil fuels) shows balanced natural flows, accumulating emissions, conservation of where the carbon goes, and the slow decline after emissions stop. A five-box toy model for trends, not a forecast."},"formula":"ΔA = E − uptake(land) − uptake(ocean)","source":"../earth/climate/carbon-cycle/#step2","lessons":[{"slug":"carbon-cycle","step":2,"category":"earth","stage":"senior","primary":true}],"note":"No earth-science group in the atlas; group left OTHER. Edges point to existing site pages (photosynthesis, climate-energy) merged separately."},
"climate-energy":{"description":{"zh":"阳光进来、红外出去，两边账要平：大气二氧化碳加厚，等于给出去的路加了道关卡，出少于进，地表就升温攒热量。气候问题本质是能量收支账，不是单日冷暖。","en":"Sunlight comes in, infrared goes out, and the two sides must balance: thicker atmospheric CO₂ puts a checkpoint on the way out, so out falls short of in and the surface warms as heat accumulates. Climate is an energy-budget ledger, not a single day's weather."},"source":"../earth/climate/climate-energy/#step2","lessons":[{"slug":"climate-energy","step":2,"category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["地球为什么变暖"],"en":["why is the planet warming"]}},
"climate-feedback":{"description":{"zh":"CO₂ 先让地球散热变难、带来一点初始升温；升温又让冰雪变少（反射的阳光减少）、空气里水汽变多（多吸红外），它们再推高温度——这些回路把一个小扰动放大，直到进出的能量重新平衡。","en":"CO₂ first makes it harder for the Earth to shed heat, causing some initial warming; that warming melts snow and ice (less sunlight reflected) and puts more water vapour in the air (more infrared absorbed), which push the temperature higher still — loops that amplify a small push until incoming and outgoing energy balance again."},"source":"../earth/climate/climate-feedback/#step2","lessons":[{"slug":"climate-feedback","step":2,"category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["气候反馈","冰雪反照率反馈","水汽反馈","正反馈","辐射强迫","全球变暖为什么会加速","气候临界点"],"en":["climate feedback","ice–albedo feedback","water vapour feedback","positive feedback","radiative forcing","why does global warming accelerate","climate tipping point"]}},
"planetary-energy-balance":{"description":{"zh":"吸收的阳光 S(1−α)/4 要等于放出的红外 σT⁴；没有大气的地球会停在约 255 K，比观测的 288 K 冷 33 K。","en":"Absorbed sunlight S(1−α)/4 must equal emitted infrared σT⁴; an airless Earth would settle near 255 K, 33 K colder than the observed 288 K."},"source":"../earth/climate/why-the-planet-warms/#ch1","lessons":[{"slug":"why-the-planet-warms","step":null,"anchor":"ch1","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["能量收支","辐射平衡","有效温度","没有大气地球多冷","反照率","太阳常数","斯特藩-玻尔兹曼定律"],"en":["energy budget","radiative balance","effective temperature","how cold would Earth be without air","albedo","solar constant","Stefan-Boltzmann law"]}},
"plate-tectonics":{"description":{"zh":"地球的硬外壳碎成许多板块，漂在缓慢流动的软流圈上，每年只移动几厘米：相互分离处长出新地壳（洋中脊），相互汇聚处一块俯冲到另一块下面（海沟、火山、山脉），相互错动处应力积累、突然释放成地震。","en":"The Earth’s rigid shell is broken into plates riding on the slowly flowing asthenosphere, moving only a few centimetres a year: where they pull apart new crust forms (mid-ocean ridges), where they converge one dives beneath the other (trenches, volcanoes, mountains), and where they slide past each other stress builds and is released as earthquakes."},"source":"../earth/geo/plate-tectonics/#step1","lessons":[{"slug":"plate-tectonics","step":1,"category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["板块运动","大陆漂移","板块边界","洋中脊 海沟","为什么会地震","火山是怎么形成的","喜马拉雅山怎么来的","俯冲带","地震","地震是怎么发生的"],"en":["plate motion","continental drift","plate boundaries","mid-ocean ridge and trench","why do earthquakes happen","how are volcanoes formed","how did the Himalayas form","subduction zone","earthquake","earthquakes","what causes earthquakes"]}},
"schwarzschild-radius":{"description":{"zh":"质量压得越小逃逸速度越大，压到 rₛ = 2GM/c² 时等于光速；这是启发式算法，真正的视界来自广义相对论。","en":"Squeeze a mass and its escape speed rises until it reaches c at r_s = 2GM/c²; a heuristic that happens to match the horizon of general relativity."},"source":"../earth/astronomy/what-is-a-black-hole/#ch1","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch1","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["黑洞","史瓦西半径","事件视界","视界","逃逸速度","黑洞是什么","光为什么逃不出黑洞","地球变成黑洞有多大"],"en":["black hole","Schwarzschild radius","event horizon","escape velocity","what is a black hole","why can't light escape a black hole","how small would Earth be as a black hole"]}},
"black-hole-size-density":{"description":{"zh":"视界半径和质量成正比，按体积平均的“密度”与质量平方成反比：超大质量黑洞可以比水还稀。","en":"Horizon radius grows in proportion to mass, so mass per volume falls as 1/M²: a supermassive black hole can be less dense than water."},"source":"../earth/astronomy/what-is-a-black-hole/#ch2","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch2","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["黑洞有多大","黑洞的密度","超大质量黑洞","黑洞比水还轻"],"en":["how big is a black hole","black hole density","supermassive black hole","black hole less dense than water"]}},
"greenhouse-one-layer":{"description":{"zh":"空气层让阳光通过、吸收地面红外并向下退回一半，地面要放出更多热才能平衡；吸收比例 0.76 时地面正好 288 K。","en":"A layer that passes sunlight but absorbs ground infrared sends half back down, so the ground must run warmer; absorbing 76 % gives exactly 288 K."},"source":"../earth/climate/why-the-planet-warms/#ch2","lessons":[{"slug":"why-the-planet-warms","step":null,"anchor":"ch2","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["温室效应","温室气体","大气逆辐射","温室效应是什么","为什么有大气地球更暖","单层大气模型"],"en":["greenhouse effect","greenhouse gases","back radiation","what is the greenhouse effect","why does an atmosphere warm the surface","one-layer atmosphere model"]}},
"black-holes-dont-suck":{"description":{"zh":"同样的距离，黑洞的引力和同样重的恒星一样：把太阳换成同质量的黑洞，地球轨道不变。","en":"At the same distance a black hole pulls like any equal mass: replace the Sun with a one-solar-mass black hole and Earth's orbit does not change."},"source":"../earth/astronomy/what-is-a-black-hole/#ch3","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch3","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["黑洞会把东西吸进去吗","太阳变成黑洞会怎样","球壳定理","黑洞吸东西"],"en":["do black holes suck things in","what if the Sun became a black hole","shell theorem","black hole vacuum cleaner"]}},
"emission-height":{"description":{"zh":"地球向太空散热的地方在高空，高空总是那个约 255 K；加厚大气把排放层抬高，下面就要更暖。","en":"Earth sheds heat from high in the air, which always sits near 255 K; a thicker atmosphere lifts that level, and everything below must warm."},"source":"../earth/climate/why-the-planet-warms/#ch3","lessons":[{"slug":"why-the-planet-warms","step":null,"anchor":"ch3","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["排放高度","有效辐射层","多层大气模型","递减率","为什么山顶更冷","加二氧化碳为什么变暖"],"en":["emission height","effective radiating level","multi-layer atmosphere","lapse rate","why is it colder higher up","why does more CO2 warm the surface"]}},
"co2-saturation-log-forcing":{"description":{"zh":"15 微米吸收带的中心早已不透明，但两侧的坡随浓度变黑，所以每翻一倍挡住的红外差不多一样多：约 3.7–4.7 W/m²。","en":"The centre of the 15 µm band is long opaque, but its sloping wings keep darkening, so every doubling blocks about the same amount: roughly 3.7–4.7 W/m²."},"source":"../earth/climate/why-the-planet-warms/#ch4","lessons":[{"slug":"why-the-planet-warms","step":null,"anchor":"ch4","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["二氧化碳饱和","吸收带饱和","辐射强迫","二氧化碳加倍","对数关系","二氧化碳不是已经饱和了吗","15微米吸收带"],"en":["CO2 saturation","band saturation","radiative forcing","CO2 doubling","logarithmic forcing","isn't CO2 already saturated","15 micron band"]}},
"isco-photon-sphere":{"description":{"zh":"离黑洞几个 rₛ 以内引力比牛顿说的强：轨道进动，3 rₛ 以内没有稳定圆轨道，1.5 rₛ 处光可以绕圈。","en":"Within a few r_s gravity is stronger than Newton's: orbits precess, no circular orbit is stable inside 3 r_s, and light can circle at 1.5 r_s."},"source":"../earth/astronomy/what-is-a-black-hole/#ch4","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch4","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["最内稳定圆轨道","ISCO","光子球","近日点进动","有效势","广义相对论轨道"],"en":["innermost stable circular orbit","ISCO","photon sphere","perihelion precession","effective potential","orbits in general relativity"]}},
"climate-feedbacks":{"description":{"zh":"加倍二氧化碳本身只带来约 1.2 K；水汽、冰雪和云把升温一轮一轮放大，合起来到约 3.4 K。","en":"Doubling CO₂ alone gives about 1.2 K; water vapour, ice and clouds amplify it round by round to about 3.4 K."},"source":"../earth/climate/why-the-planet-warms/#ch5","lessons":[{"slug":"why-the-planet-warms","step":null,"anchor":"ch5","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["气候反馈","水汽反馈","冰雪反照率反馈","云反馈","正反馈","普朗克反馈","平衡气候敏感度","气候敏感度"],"en":["climate feedback","climate sensitivity","water vapour feedback","ice-albedo feedback","cloud feedback","positive feedback","Planck feedback","equilibrium climate sensitivity"]}},
"spaghettification":{"description":{"zh":"头脚之间的引力差在视界上与质量平方成反比：小黑洞在视界外就把人撕开，大黑洞可以平安穿过。","en":"The head-to-foot difference in pull at the horizon falls as 1/M²: small black holes tear you apart outside, large ones let you cross intact."},"source":"../earth/astronomy/what-is-a-black-hole/#ch5","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch5","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["面条化","潮汐力","掉进黑洞会怎样","被黑洞撕碎","人能穿过视界吗"],"en":["spaghettification","tidal force","what happens if you fall into a black hole","torn apart by a black hole","can you survive crossing the event horizon"]}},
"gravitational-time-dilation":{"description":{"zh":"悬停在 r 处的钟按 √(1 − rₛ/r) 变慢，越近视界越慢；GPS 卫星每天要为此修正几十微秒。","en":"A clock hovering at r ticks at √(1 − r_s/r), slower near the horizon; GPS satellites correct for tens of microseconds a day."},"source":"../earth/astronomy/what-is-a-black-hole/#ch6","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch6","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["引力时间膨胀","黑洞附近时间变慢","引力红移","星际穿越 时间","GPS 相对论"],"en":["gravitational time dilation","time slows near a black hole","gravitational redshift","Interstellar time dilation","GPS relativity"]}},
"sensitivity-uncertainty":{"description":{"zh":"敏感度 = 无反馈升温 ÷ (1 − f)。f 的不确定是对称的，除出来的敏感度却拖着一条长长的高尾巴。","en":"Sensitivity = no-feedback warming ÷ (1 − f). A symmetric uncertainty in f becomes a long high tail in sensitivity."},"source":"../earth/climate/why-the-planet-warms/#ch6","lessons":[{"slug":"why-the-planet-warms","step":null,"anchor":"ch6","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["气候敏感度区间","敏感度不确定性","长尾分布","为什么预测范围这么大","气候敏感度是多少"],"en":["climate sensitivity range","sensitivity uncertainty","fat tail","why is the range so wide","how sensitive is the climate"]}},
"black-hole-shadow":{"description":{"zh":"瞄准中心 2.6 rₛ 以内的光都被吞掉，所以看到的黑影约是视界的 2.6 倍；EHT 拍到的人马座 A* 与之一致。","en":"Light aimed within 2.6 r_s is captured, so the dark shadow is about 2.6 times the horizon; the EHT image of Sgr A* agrees."},"source":"../earth/astronomy/what-is-a-black-hole/#ch7","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch7","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["黑洞照片","黑洞的影子","事件视界望远镜","EHT","黑洞阴影","光线弯曲"],"en":["black hole image","black hole shadow","Event Horizon Telescope","EHT","photon ring","light bending"]}},
"ocean-lag":{"description":{"zh":"海洋像一锅需要慢慢烧开的水：二氧化碳加倍那年只走完一部分升温，剩下的要几十到几百年，取决于参与的水有多深。","en":"The ocean is a slow pot to heat: when CO₂ has doubled only part of the warming has arrived, and the rest takes decades to centuries depending on how deep the mixed water goes."},"source":"../earth/climate/why-the-planet-warms/#ch7","lessons":[{"slug":"why-the-planet-warms","step":null,"anchor":"ch7","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["海洋热惯性","气候滞后","时间常数","瞬时气候响应","为什么停止排放还会变暖","海洋吸热"],"en":["ocean heat inertia","climate lag","time constant","transient climate response","warming in the pipeline","ocean heat uptake"]}},
"sgr-a-star-s2":{"description":{"zh":"S2 绕银河系中心一圈 16 年，开普勒第三定律给出约 426 万个太阳质量挤在约 120 个日地距离以内。","en":"S2 circles the Galactic Centre every 16 years; Kepler's third law puts about 4.26 million solar masses inside about 120 AU."},"source":"../earth/astronomy/what-is-a-black-hole/#ch8","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch8","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["人马座 A*","银河系中心黑洞","S2 恒星","怎么知道黑洞存在","开普勒第三定律 称质量"],"en":["Sagittarius A*","Sgr A*","Milky Way black hole","star S2","how do we know black holes exist","weighing a black hole"]}},
"gravitational-wave-chirp":{"description":{"zh":"两个黑洞绕转时辐射引力波、越绕越快，频率上扫成“啁啾”；GW150914 是 36 和 29 个太阳质量的合并。","en":"Orbiting black holes radiate gravitational waves and spiral in, sweeping up in frequency as a chirp; GW150914 was a 36 + 29 solar-mass merger."},"source":"../earth/astronomy/what-is-a-black-hole/#ch9","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch9","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["引力波","LIGO","黑洞合并","啁啾","GW150914"],"en":["gravitational waves","LIGO","black hole merger","chirp","GW150914"]}},
"hawking-radiation-limits":{"description":{"zh":"总结：远看是质量，近看改变轨道、时间和光；霍金辐射对天体黑洞可以忽略，视界以内本页不做断言。","en":"Summary: from afar just a mass, up close it reshapes orbits, time and light; Hawking radiation is negligible for astrophysical holes, and nothing is claimed about the interior."},"source":"../earth/astronomy/what-is-a-black-hole/#ch10","lessons":[{"slug":"what-is-a-black-hole","step":null,"anchor":"ch10","category":"earth","stage":"senior","primary":true}],"aliases":{"zh":["霍金辐射","黑洞会蒸发吗","黑洞里面有什么","奇点","黑洞的温度"],"en":["Hawking radiation","do black holes evaporate","what is inside a black hole","singularity","black hole temperature"]}},
"cosmic-expansion":{"description":{"zh":"不是星系在静止的空间里从一个中心飞散，而是空间的刻度本身在拉开：所有星系间的距离按同一个尺度因子变大，所以越远的星系退行得越快（v = H₀d），它们发出的光在路上也被拉长成红移。","en":"Galaxies are not flying apart from a centre through still space; the ruler of space itself is stretching: every distance between galaxies grows by the same scale factor, so farther galaxies recede faster (v = H₀d), and their light is stretched into a redshift on the way."},"formula":"v = H₀d,  λ = (1+z)λ₀","source":"../earth/astronomy/cosmology-expansion/#step1","lessons":[{"slug":"cosmology-expansion","step":1,"category":"earth","stage":"university","primary":true}],"aliases":{"zh":["宇宙膨胀","哈勃定律","哈勃常数","宇宙学红移","尺度因子","宇宙有中心吗","星系为什么在远离我们","大爆炸","宇宙大爆炸"],"en":["expanding universe","Hubble’s law","Hubble constant","cosmological redshift","scale factor","does the universe have a centre","why are galaxies moving away from us","Big Bang","big bang","the big bang","hubble's law"]}},
"kepler-orbits":{"description":{"zh":"行星沿椭圆绕恒星运行，恒星在一个焦点上；偏心率越大，椭圆越扁；离恒星近时跑得快、远时跑得慢（开普勒第二定律）；当轨道恰好侧对着我们，行星经过恒星前方会挡住一点星光，这就是凌日。","en":"A planet travels round its star on an ellipse with the star at one focus; the larger the eccentricity, the flatter the ellipse; it moves fast when close to the star and slowly when far (Kepler’s second law); when the orbit is seen edge-on, the planet passing in front of the star blocks a little of its light — a transit."},"source":"../earth/astronomy/kepler-orbits/","lessons":[{"slug":"kepler-orbits","step":null,"category":"earth","stage":"university","primary":true}],"aliases":{"zh":["开普勒定律","椭圆轨道","开普勒第二定律","面积定律","偏心率","近日点 远日点","凌日法找系外行星","行星为什么离太阳近时更快","开普勒三定律","行星轨道"],"en":["Kepler’s laws","elliptical orbit","Kepler’s second law","law of equal areas","eccentricity","perihelion and aphelion","transit method for exoplanets","why do planets move faster near the sun","kepler's laws","planetary orbits"]}}
}});
